use xiom.io;

enum Activity {
  Work(hours: Int),
  Exercise(minutes: Int),
  Rest,
  Social(friends: Int),
}

type DayPlan = {
  day: Str;
  activity: Activity;
}

fn DayPlan.summary(self) -> Str {
  match activity {
    Work(hours) => { return day + ": Work for " + hours + " hours"; }
    Exercise(minutes) => { return day + ": Exercise for " + minutes + " minutes"; }
    Rest => { return day + ": Rest day"; }
    Social(friends) => { return day + ": Hang out with " + friends + " friends"; }
  }
}

fn main() -> Int {
  let monday = DayPlan{ day: "Monday"; activity: Activity.Work(8); };
  let tuesday = DayPlan{ day: "Tuesday"; activity: Activity.Exercise(45); };
  let wednesday = DayPlan{ day: "Wednesday"; activity: Activity.Rest; };
  match monday.activity {
    Work(hours) => { return hours; }
    _ => { return 0; }
  }
}
